    30|function readTrimmed(value: unknown): string {
    31|  return typeof value === 'string' ? value.trim() : '';
    32|}
    33|
    34|function nowIso(): string {
    35|  return new Date().toISOString();
    36|}
    37|
    38|function getSupabaseUrl(): string {
    39|  for (const name of SUPABASE_URL_NAMES) {
    40|    const value = readTrimmed(process.env[name]).replace(/\/+$/, '');
    41|    if (value) return value;
    42|  }
    43|  return '';
    44|}
    45|
    46|function getServiceRoleKey(): string {
    47|  for (const name of SERVICE_ROLE_NAMES) {
    48|    const value = readTrimmed(process.env[name]);
    49|    if (value) return value;
    50|  }
    51|  return '';
    52|}
