   152|        doc_key text primary key,
   153|        value jsonb not null default '[]'::jsonb,
   154|        updated_at timestamptz not null default now()
   155|      )`,
   156|      `create table if not exists public.ivx_durable_events (
   157|        id bigserial primary key,
   158|        doc_key text not null,
   159|        event jsonb not null,
   160|        created_at timestamptz not null default now()
   161|      )`,
   162|      'alter table public.ivx_durable_documents enable row level security',
   163|      'alter table public.ivx_durable_events enable row level security',
   164|      'create index if not exists ivx_durable_events_key_created_idx on public.ivx_durable_events (doc_key, created_at asc)',
   165|      "comment on table public.ivx_durable_documents is 'IVX durable business state (leads/CRM/deals/outreach/pipeline). Backend service-role only.'",
   166|      "select pg_notify('pgrst','reload schema')",
   167|    ];
   168|    for (const statement of statements) {
   169|      await this.executeSql(statement);
   170|    }
   171|    await sleep(400);
   172|    console.log('[IvxDurableStore] Schema ready', { marker: SCHEMA_MARKER });
   173|  }
   174|
   175|  private async restRequest<T>(
   176|    pathName: string,
   177|    init: RequestInit = {},
   178|    prefer?: string,
   179|    retrySchemaCache: boolean = true,
   180|  ): Promise<T> {
